// Renders the feed against fixture data, so the layout can be eyeballed
// without going through the email OTP gate.
import { StrictMode, useEffect, useState } from 'react'
import { createRoot } from 'react-dom/client'
import { fitBand } from './lib/useFeed'
import './styles.css'

// Fixture is generated by tools/make_preview.py and gitignored: it can carry
// real contact names, which must never enter the repo.
const SAMPLE = [{
  id: 'sample', title: 'Senior Copywriter', company_raw: 'Example Co',
  location: 'New York, NY', posted_on: new Date().toISOString().slice(0, 10),
  url: '#', fit: 70, fit_reasons: ['title matches "senior copywriter"'],
  contacts_at_company: null, contact_name: null, strength: null,
}]

function ago(d) {
  if (!d) return ''
  const days = Math.round((Date.now() - new Date(d).getTime()) / 86400000)
  return days <= 0 ? 'today' : days === 1 ? 'yesterday' : `${days}d ago`
}
function money(lo, hi) {
  if (!lo && !hi) return null
  const k = (n) => `$${Math.round(n / 1000)}k`
  return lo && hi ? `${k(lo)}–${k(hi)}` : k(lo || hi)
}
function heat(s) { return s == null ? 'none' : s >= 11 ? 'hot' : s >= 9 ? 'warm' : 'mild' }

function Preview() {
  const [rows, setRows] = useState(SAMPLE)
  useEffect(() => {
    fetch('./previewData.json')
      .then((r) => (r.ok ? r.json() : null))
      .then((d) => d && d.length && setRows(d))
      .catch(() => {})
  }, [])

  return (
    <div className="app">
      <header className="top">
        <h1>warm</h1>
        <nav className="views">
          <button className="view is-active">Jobs</button>
          <button className="view">Import</button>
          <button className="view">Setup</button>
        </nav>
      </header>
      <nav className="tabs">
        {['Best', 'Warm', 'Strong fit', 'All new', 'Interested', 'Applied'].map((t, i) => (
          <button key={t} className={`tab ${i === 2 ? 'is-active' : ''}`}>{t}</button>
        ))}
      </nav>
      <ul className="cards">
        {rows.slice(0, 14).map((row) => {
          const fb = fitBand(row.fit)
          const pay = money(row.salary_min, row.salary_max)
          const both = row.contact_name && fb === 'strong'
          return (
            <li key={row.id} className={`card card-${heat(row.strength)}`}>
              <div className="card-head">
                <a className="card-title" href={row.url}>{row.title}</a>
                <span className={`fit fit-${fb}`}>{row.fit}</span>
              </div>
              <div className="card-sub">
                {row.company_raw}
                {row.location && <span className="muted"> · {row.location}</span>}
                {row.posted_on && <span className="muted"> · {ago(row.posted_on)}</span>}
              </div>
              <div className="chips">
                {both && <span className="chip chip-both">warm + strong fit</span>}
                {pay && <span className="chip">{pay}</span>}
                {row.workplace && <span className="chip">{row.workplace}</span>}
                {row.seniority_level && row.seniority_level !== 'Not Applicable' && (
                  <span className="chip">{row.seniority_level}</span>
                )}
              </div>
              {row.contact_name && (
                <div className="conn">
                  <span className={`dot dot-${heat(row.strength)}`} />
                  <div>
                    <div className="conn-name">
                      {row.contact_name}
                      {row.contact_role && <span className="conn-role"> · {row.contact_role}</span>}
                    </div>
                    <div className="conn-meta">via {row.source_label}</div>
                  </div>
                </div>
              )}
              {!!(row.fit_reasons || []).length && (
                <ul className="why-list">
                  {row.fit_reasons.slice(0, 3).map((r, i) => <li key={i}>{r}</li>)}
                </ul>
              )}
              <div className="actions">
                <button>Interested</button>
                <button>Applied</button>
                <button className="ghost">Skip</button>
              </div>
            </li>
          )
        })}
      </ul>
    </div>
  )
}

createRoot(document.getElementById('root')).render(<StrictMode><Preview /></StrictMode>)
